import json
with open('/app/resources/treasury_bulletin_2007_12.json', 'r') as f:
    data = json.load(f)
doc = data['document']
# Let's look for elements that mention TIPS, price, etc.
for i, page in enumerate(doc.get('pages', [])):
    if 'elements' in page:
        for elem in page.get('elements', []):
            text = elem.get('text', '') if isinstance(elem, dict) else str(elem)
            if 'TIPS' in text and ('price' in text.lower() or 'adjusted' in text.lower()):
                print(f'Page {i}: {text[:200]}')
